function relatorio(texto) {
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const linhas=String(texto??'').split(/\r?\n/).filter(x=>x.trim());
  const grupos=new Map(); const invalidas=[];
  linhas.forEach((linha,i)=>{
    const k=linha.indexOf('|'); const assunto=linha.slice(0,k).trim(); const duvida=linha.slice(k+1).trim();
    if(k<1||!assunto||!duvida){invalidas.push(i+1);return;}
    const chave=assunto.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
    if(!grupos.has(chave))grupos.set(chave,{assunto,duvidas:[]});
    grupos.get(chave).duvidas.push(duvida);
  });
  const assuntos=[...grupos.values()].sort((a,b)=>b.duvidas.length-a.duvidas.length||a.assunto.localeCompare(b.assunto,'pt-BR'));
  const total=assuntos.reduce((n,g)=>n+g.duvidas.length,0);
  const mensagem=invalidas.length?`Revise as linhas ${invalidas.join(', ')}: use assunto | dúvida. O relatório está parcial.`:total?'Relatório pronto para o professor revisar.':'Nenhuma dúvida válida recebida.';
  const html=`<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FIAT — Relatório de dúvidas</title><style>body{font:18px/1.6 system-ui;background:#f3f6fa;color:#162c43;padding:28px}main{max-width:900px;margin:auto}section{background:white;border:1px solid #d7e1eb;padding:20px;border-radius:14px;margin:18px 0}h1{line-height:1.2}small{color:#526476}</style></head><body><main><small>FIAT · DA INFORMAÇÃO AO MATERIAL DE APOIO</small><h1>O que revisar com a turma?</h1><p>${total} ${total === 1 ? 'dúvida' : 'dúvidas'} · ${assuntos.length} ${assuntos.length === 1 ? 'assunto' : 'assuntos'} · ${invalidas.length} ${invalidas.length === 1 ? 'linha' : 'linhas'} a corrigir</p><p>${esc(mensagem)}</p>${assuntos.map(g=>`<section><h2>${esc(g.assunto)} — ${g.duvidas.length} ${g.duvidas.length === 1 ? 'dúvida' : 'dúvidas'}</h2><ul>${g.duvidas.map(d=>`<li>${esc(d)}</li>`).join('')}</ul><p><strong>Pauta sugerida:</strong> revisar este assunto e selecionar um exemplo que ajude a discutir as dúvidas acima.</p></section>`).join('')}<p><small>A contagem mede dúvidas recebidas, não dificuldade, domínio ou quantidade de alunos. Os assuntos foram informados na entrada; não houve classificação por IA.</small></p></main></body></html>`;
  return {total_duvidas:total,assuntos,linhas_invalidas:invalidas,parcial:invalidas.length>0,html};
}

return $input.all().map((x,i)=>({json:relatorio(x.json.duvidas),pairedItem:{item:i}}));
